(() => {
  "use strict";

  const $ = (id) => document.getElementById(id);
  const setup = $("setup");
  const selectionBox = setup?.querySelector(".selection-box");
  const modeTabs = setup?.querySelector(".mode-tabs");
  const resultSection = $("resultSection");
  const resultHead = resultSection?.querySelector(".result-head");
  const resultTitle = resultHead?.querySelector("h2");
  const paperView = $("paperView");
  const generateButton = $("generateButton");
  const regenerateButton = $("regenerateButton");
  const schoolSelect = $("schoolSelect");
  const pairSelect = $("pairSelect");
  const tabOne = $("tabOne");
  const tabTwo = $("tabTwo");
  let celebratePending = false;

  if (modeTabs && selectionBox && !$("welcomeCard")) {
    const welcome = document.createElement("section");
    welcome.id = "welcomeCard";
    welcome.className = "welcome-card";
    welcome.innerHTML = `
      <div><h2>今天，来练一套吧。</h2><p>按目标院校题型与分值生成真题练习卷。</p></div>
      <div class="hero-parrot-wrap">
        <img class="hero-parrot" src="data:image/webp;base64," alt="抱着录取通知书的小鹦鹉">
      </div>`;
    selectionBox.insertAdjacentElement("beforebegin", welcome);
  }

  if (resultHead && !resultHead.querySelector(".success-parrot")) {
    resultHead.insertAdjacentHTML("beforeend", `
      <div class="success-parrot-wrap">
        <img class="success-parrot" src="data:image/webp;base64," alt="举起录取通知书庆祝的小鹦鹉">
      </div>
      <span class="success-star" aria-hidden="true">✦</span>`);
  }

  if (pairSelect && !$("pairFullText")) {
    const fullText = document.createElement("p");
    fullText.id = "pairFullText";
    fullText.className = "pair-full-text";
    pairSelect.insertAdjacentElement("afterend", fullText);
  }

  function syncPairText() {
    const text = pairSelect?.selectedOptions?.[0]?.textContent?.trim() || "";
    const fullText = $("pairFullText");
    if (fullText) fullText.textContent = text;
    if (pairSelect) pairSelect.title = text;
  }

  function syncSubjectLabels() {
    const one = $("templateOne")?.querySelector("h3")?.textContent?.trim();
    const two = $("templateTwo")?.querySelector("h3")?.textContent?.trim();
    if (one) tabOne.textContent = one;
    if (two) tabTwo.textContent = two;
  }

  function decoratePaper() {
    const title = paperView?.querySelector(".paper-header h3");
    if (title && !title.textContent.endsWith(" · 模考卷")) title.textContent += " · 模考卷";
    if (!title) return;
    const activeTemplate = tabTwo?.classList.contains("active") ? $("templateTwo") : $("templateOne");
    const year = activeTemplate?.querySelector(".template-meta")?.textContent?.match(/(?:19|20)\d{2}/)?.[0] || "年份待核实";
    let reference = title.parentElement.querySelector(".template-reference");
    if (!reference) {
      reference = document.createElement("p");
      reference.className = "template-reference";
      title.insertAdjacentElement("afterend", reference);
    }
    const referenceText = year === "年份待核实" ? year : `参照 ${year} 年真题结构`;
    if (reference.textContent !== referenceText) reference.textContent = referenceText;
    const note = title.parentElement.querySelector(".mock-note");
    const noteText = "按目标院校的题型与分值，从其他院校真题中选题组卷。";
    if (note && note.textContent !== noteText) note.textContent = noteText;
  }

  function clearResultMode() {
    document.body.classList.remove("has-mock-result");
    resultHead?.classList.remove("celebrate");
  }

  function showResultMode() {
    if (!resultSection || resultSection.classList.contains("is-hidden")) return;
    document.body.classList.add("has-mock-result");
    if (resultTitle) resultTitle.textContent = schoolSelect?.value || "模考卷";
    syncSubjectLabels();
    decoratePaper();
    if (celebratePending && resultHead) {
      celebratePending = false;
      resultHead.classList.remove("celebrate");
      requestAnimationFrame(() => resultHead.classList.add("celebrate"));
      window.setTimeout(() => resultHead.classList.remove("celebrate"), 650);
    }
  }

  function beginGeneration(button) {
    celebratePending = true;
    const original = button.dataset.label || button.textContent;
    button.dataset.label = original;
    button.textContent = "正在组卷…";
    window.setTimeout(() => {
      button.textContent = original;
      showResultMode();
    }, 180);
  }

  generateButton?.addEventListener("click", () => beginGeneration(generateButton));
  regenerateButton?.addEventListener("click", () => beginGeneration(regenerateButton));
  schoolSelect?.addEventListener("change", () => {
    clearResultMode();
    window.setTimeout(() => { syncSubjectLabels(); syncPairText(); }, 0);
  });
  pairSelect?.addEventListener("change", () => {
    clearResultMode();
    window.setTimeout(() => { syncSubjectLabels(); syncPairText(); }, 0);
  });
  $("modeHistory")?.addEventListener("click", () => {
    clearResultMode();
    document.body.classList.add("history-mode");
  });
  $("modeMock")?.addEventListener("click", () => {
    document.body.classList.remove("history-mode");
    if (!resultSection?.classList.contains("is-hidden")) showResultMode();
  });

  if (paperView) {
    new MutationObserver(decoratePaper).observe(paperView, { childList: true, subtree: true });
  }

  window.setTimeout(() => { syncSubjectLabels(); syncPairText(); }, 0);
})();

